                ["iconFile"] = "/esoui/art/icons/quest_cwc_inc_book002.dds",
                ["itemId"] = 133242,
                ["fTxt"] = 
                {
                    [1] = "Proctor Luciana has served Sotha Sil for many long centuries. Her writings on battle and philosophy contain lifetimes of hard-earned knowledge that can temporarily expand the reader's mind.",
                    [2] = "PROCTOR LUCIANA HAS SERVED SOTHA SIL FOR MANY LONG CENTURIES. HER WRITINGS ON BATTLE AND PHILOSOPHY CONTAIN LIFETIMES OF HARD-EARNED KNOWLEDGE THAT CAN TEMPORARILY EXPAND THE READER'S MIND.",
                },
